<template>
  <section class="narriva-compliance" aria-label="Narriva Clinical Compliance Check" :aria-busy="busy">
    <header><div><img :src="NARRIVA_BRAND.compliance" alt="Narriva Compliance by AuricWell" /><h2>Narriva Clinical Compliance Check <span>5 checks</span></h2></div><img class="narriva-compliance__shield" :src="verified ? NARRIVA_BRAND.verified : NARRIVA_BRAND.notVerified" :alt="verified ? 'Narriva checks passed' : 'Not verified'" /></header>
    <p v-if="error" class="narriva-compliance__error" role="alert">{{ error }}</p>
    <p v-if="!review && !busy" class="narriva-compliance__hint">Generate your note to check its documentation. A check is confirmed only after Narriva returns its result.</p>
    <p v-if="review?.status === 'stale'" class="narriva-compliance__error">The note changed. Run the checks again before Quick Sign.</p>
    <section v-if="review || busy" class="narriva-score" :class="{ 'narriva-score--passed': verified }" aria-label="Documentation quality score">
      <div class="narriva-score__summary"><div><span>Documentation quality</span><strong v-if="scoring">{{ scoring.score }}<small>%</small></strong><strong v-else class="narriva-score__unavailable">{{ busy ? 'Checking…' : 'Score unavailable' }}</strong></div><div><strong>{{ scoreOutcome }}</strong><p v-if="scoring">Required score: {{ scoring.threshold }}% · All 5 required checks must also pass.</p><p v-else>A saved-note review must return a score before verification is available.</p></div></div>
      <p v-if="scoring?.explanation">{{ scoring.explanation }}</p>
      <div v-if="mandatoryBlockers.length || scoring?.mandatoryPassed === false" class="narriva-score__blockers"><strong>Required checks blocking approval</strong><ul v-if="mandatoryBlockers.length"><li v-for="check in mandatoryBlockers" :key="check.id">{{ check.label }} · {{ label(check.status) }}</li></ul><p v-else>The required checks have not been confirmed. Run the checks again.</p></div>
      <details v-if="scoring?.criteria?.length" class="narriva-score__criteria"><summary>View score breakdown</summary><ul><li v-for="criterion in scoring.criteria" :key="criterion.id"><div><strong>{{ criterion.label }}</strong><span>{{ criterionLabel(criterion) }}</span></div><p v-if="criterion.message">{{ criterion.message }}</p><blockquote v-for="(evidence, index) in criterionEvidence(criterion)" :key="index">{{ evidence }}</blockquote></li></ul></details>
      <ul v-if="scoring?.findings?.length" class="narriva-check__findings narriva-score__findings"><li v-for="finding in scoring.findings" :key="finding.id"><p>{{ finding.message }}</p><p v-if="finding.bypassed || finding.status === 'bypassed'" class="narriva-check__bypass-record">Kept as written. {{ finding.bypassReason || finding.reason || '' }} Quick Sign is unavailable.</p><template v-else><button v-if="finding.action && finding.action !== 'none'" type="button" :disabled="busy || readOnly" @click="$emit('action', { checkId: 'scoring', finding })">{{ actionLabel(finding.action) }}</button><button v-if="finding.canBypass && !readOnly" type="button" :disabled="busy" @click="openBypass = openBypass === finding.id ? '' : finding.id">Keep my note as it is</button><form v-if="openBypass === finding.id && finding.canBypass && !readOnly" @submit.prevent="bypass(finding)"><label>Reason for keeping this note<textarea v-model="reasons[finding.id]" rows="2" minlength="5" maxlength="2000" required :disabled="busy" /></label><small>This records your decision and removes Quick Sign eligibility.</small><button type="submit" :disabled="busy || (reasons[finding.id]?.trim().length || 0) < 5">Record decision</button></form></template></li></ul>
      <p v-if="scoring?.disclaimer" class="narriva-compliance__hint">{{ scoring.disclaimer }}</p>
    </section>
    <ol>
      <li v-for="(check, index) in checks" :key="check.id" :class="`narriva-check--${check.status}`">
        <div class="narriva-check__title"><span class="narriva-check__state" :class="{ spinning: check.status === 'running' }" aria-hidden="true">{{ symbol(check.status) }}</span><strong>{{ index + 1 }}. {{ check.label }}</strong><span>{{ label(check.status) }}</span></div>
        <ul v-if="check.findings?.length" class="narriva-check__findings"><li v-for="finding in check.findings" :key="finding.id">
          <p>{{ finding.message }}</p>
          <p v-if="finding.bypassed || finding.status === 'bypassed'" class="narriva-check__bypass-record">Kept as written. {{ finding.bypassReason || finding.reason || '' }} Quick Sign is unavailable.</p>
          <template v-else>
            <button v-if="finding.action && finding.action !== 'none'" type="button" :disabled="busy || readOnly" @click="$emit('action', { checkId: check.id, finding })">{{ actionLabel(finding.action) }}</button>
            <button v-if="finding.canBypass && !readOnly" type="button" :disabled="busy" @click="openBypass = openBypass === finding.id ? '' : finding.id">Keep my note as it is</button>
            <form v-if="openBypass === finding.id && finding.canBypass && !readOnly" @submit.prevent="bypass(finding)"><label>Reason for keeping this note<textarea v-model="reasons[finding.id]" rows="2" minlength="5" maxlength="2000" required :disabled="busy" /></label><small>This records your decision and removes Quick Sign eligibility.</small><button type="submit" :disabled="busy || (reasons[finding.id]?.trim().length || 0) < 5">Record decision</button></form>
          </template>
        </li></ul>
        <slot v-if="check.id === 'risk_safety'" name="risk" :required="riskAssessmentRequired || review?.riskAssessmentRequired === true" />
      </li>
    </ol>
    <footer><span v-if="review?.quickSignEligible === true && verified" class="narriva-compliance__eligible"><img :src="NARRIVA_BRAND.quickSign" alt="Narriva Quick Sign Approved" /></span><span v-else-if="review?.status === 'bypassed'">Review decisions saved. Use the standard signature review.</span><span v-else-if="verified">Documentation checks passed.</span><span v-else>{{ busy ? 'Checking the current note…' : 'Review and resolve any findings before signing.' }}</span><button v-if="review || error" type="button" :disabled="busy || readOnly" @click="$emit('retry')">{{ busy ? 'Checking…' : 'Run checks again' }}</button></footer>
  </section>
</template>
<script setup>
import { computed, reactive, ref, watch } from 'vue';
import { NARRIVA_BRAND, NARRIVA_CHECKS } from '../../config/narrivaBrand.js';
const props = defineProps({ review: { type: Object, default: null }, busy: Boolean, error: { type: String, default: '' }, readOnly: Boolean, riskAssessmentRequired:Boolean });
const emit = defineEmits(['retry', 'resolve', 'action']);
const reasons = reactive({}), openBypass = ref('');
watch(() => props.review?.id, () => { openBypass.value=''; for(const key of Object.keys(reasons))delete reasons[key]; });
const checks = computed(() => NARRIVA_CHECKS.map((item, index) => ({ ...item, ...(props.review?.checks || []).find(check => check.id === item.id), label: item.label, status: (props.review?.checks || []).find(check => check.id === item.id)?.status || (props.busy && !props.review && index === 0 ? 'running' : 'pending') })));
const scoring = computed(() => {
  const value = props.review?.scoring;
  return value && typeof value.score === 'number' && Number.isFinite(value.score) && value.score >= 0 && value.score <= 100 && value.threshold === 70 ? value : null;
});
const verified = computed(() => !props.busy && props.review?.status === 'passed' && scoring.value?.passed === true && scoring.value.mandatoryPassed === true && scoring.value.qualityPassed !== false && scoring.value.score >= scoring.value.threshold && checks.value.every(check => check.status === 'passed'));
const mandatoryBlockers = computed(() => checks.value.filter(check => check.status !== 'passed'));
const scoreOutcome = computed(() => {
  if (props.busy || ['pending', 'running'].includes(props.review?.status)) return 'Review in progress';
  if (props.review?.status === 'stale') return 'Changed · run checks again';
  if (props.review?.status === 'bypassed') return 'Kept as written · not approved';
  if (['unavailable', 'failed'].includes(props.review?.status) || !scoring.value) return 'Review unavailable';
  if (verified.value) return 'Pass';
  return mandatoryBlockers.value.length || scoring.value.mandatoryPassed !== true ? 'Blocked · required checks need review' : 'Does not pass';
});
function criterionLabel(criterion) {
  if (criterion.status === 'not_applicable') return 'Not applicable · excluded';
  const state = { met: 'Met', missing: 'Missing', pending: 'Pending', uncertain: 'Uncertain' }[criterion.status] || 'Not confirmed';
  return typeof criterion.earned === 'number' && Number.isFinite(criterion.earned) && typeof criterion.possible === 'number' && Number.isFinite(criterion.possible) ? `${criterion.earned} / ${criterion.possible} points · ${state}` : state;
}
const criterionEvidence = criterion => (Array.isArray(criterion.evidence) ? criterion.evidence : []).map(item => typeof item === 'string' ? item : item?.excerpt || item?.text).filter(item => typeof item === 'string' && item.trim());
const label = value => ({ pending: 'Waiting', running: 'Checking', passed: 'Confirmed', action_required: 'Review needed', bypassed: 'Kept as written', unavailable: 'Unavailable', failed: 'Unavailable', stale: 'Changed' }[value] || 'Waiting');
const symbol = value => ({ passed: '✓', running: '◌', action_required: '!', bypassed: '–', unavailable: '!', failed: '!' }[value] || '○');
const actionLabel = action => ({ assessment:'Add assessment or attachment',encounter:'Review encounter details',clinical_context:'Review clinical context',edit_note:'Edit note content',risk_assessment: 'Open risk assessment', add_risk_assessment: 'Open risk assessment', clinical_service:'Review clinical service', service_code: 'Review service code', change_service_code: 'Review service code', participants: 'Review participants', review_participants: 'Review participants', consent: 'Review consent', add_assessment: 'Add assessment or attachment', treatment_plan: 'Review treatment plan', narrative: 'Edit Session Narrative' }[typeof action === 'string' ? action : action?.id] || action?.label || 'Review this finding');
function bypass(finding) { const reason = reasons[finding.id]?.trim(); if (!reason || reason.length < 5 || !finding.canBypass || props.busy) return; emit('resolve', { findingId: finding.id, action: 'bypass', reason }); openBypass.value = ''; }
</script>
<style scoped>
