_shield{width:55px;height:55px;object-fit:contain}.narriva-compliance ol{list-style:none;padding:0;margin:0}.narriva-compliance ol>li{border-top:1px solid #e3eaf1;padding:13px 0}.narriva-check__title{display:flex;align-items:center;gap:10px}.narriva-check__title>strong{flex:1;font-size:14px}.narriva-check__title>span:last-child{font-size:11px;color:#657b8e;text-align:right}.narriva-check__state{display:grid;place-items:center;width:25px;height:25px;border:1px solid #c9d6e2;color:#71889b;border-radius:50%;font-size:18px;flex:none}.narriva-check--passed .narriva-check__state{background:#e7f6ef;border-color:#b6deca;color:#26724e}.narriva-check--action_required .narriva-check__state,.narriva-check--unavailable .narriva-check__state{color:#9c651a;border-color:#e2c593;background:#fff7e8}.narriva-check__findings{list-style:none;margin:8px 0 0 35px;padding:0;font-size:13px;line-height:1.5}.narriva-check__findings p{margin:6px 0}.narriva-check__findings button,.narriva-compliance footer>button{font:inherit;font-size:12px;border:1px solid #cbd9e5;border-radius:7px;background:#f8fbfe;padding:7px 9px;color:#205782;margin:3px 7px 3px 0;cursor:pointer}.narriva-check__findings button:disabled,.narriva-compliance footer>button:disabled{opacity:.5;cursor:default}.narriva-check__findings form{background:#f7f9fc;padding:10px;margin:8px 0;border-radius:8px}.narriva-check__findings label{display:block}.narriva-check__findings textarea{display:block;box-sizing:border-box;width:100%;font:inherit;border:1px solid #c5d4e2;border-radius:6px;margin:5px 0;padding:8px}.narriva-check__findings small{display:block;color:#7b6b4c}.narriva-compliance footer{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e3eaf1;padding-top:12px;gap:10px;font-size:12px;color:#62778b}.narriva-compliance__eligible img{width:245px;max-width:100%;height:auto}.narriva-compliance__error{color:#a12c29;font-size:13px}.narriva-compliance__hint{font-size:13px;color:#647c90}.spinning{animation:narriva-spin 1s linear infinite}@keyframes narriva-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spinning{animation:none}}@media(max-width:600px){.narriva-score__summary{align-items:flex-start;gap:12px}.narriva-score__criteria li>div{flex-wrap:wrap}.narriva-compliance{padding:14px}.narriva-check__title{gap:7px}.narriva-check__title>strong{font-size:13px}.narriva-compliance header>div>img{width:220px}.narriva-compliance footer{align-items:flex-start}.narriva-check__findings{margin-left:0}}
</style>
